-- The client's mission statement (2026-11-13, ADR-023): tagline, site description, SEO defaults and the About page.
-- Data only, written in the client's own words (English). Studio -> Settings can still change the tagline and description.
-- Fresh databases get the same settings from supabase/seed.sql (site_settings rows are created there, after migrations).
-- Rollback: the previous values are listed in ADR-023; the About page body before this was the starter placeholder.

update public.site_settings set value = value || jsonb_build_object(
  'tagline', 'The People''s Voice. The Public''s Watchdog.',
  'tagline_en', 'The People''s Voice. The Public''s Watchdog.',
  'description', 'Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government.',
  'description_en', 'Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government.')
where key = 'general';

update public.site_settings set value = value || jsonb_build_object(
  'default_title', 'Boses ng Bayan — The People''s Voice. The Public''s Watchdog.',
  'default_description', 'Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government.')
where key = 'seo';

-- Body rendered with renderRichText (src/lib/rich-text/render.ts), the renderer Studio uses on save.
insert into public.pages (slug, title, summary, body, body_html, body_text, status, published_at)
values (
  'tungkol',
  'Tungkol sa Boses ng Bayan',
  'The People''s Voice. The Public''s Watchdog.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government."}]},{"type":"paragraph","content":[{"type":"text","text":"More than a public opinion research platform, Boses ng Bayan serves as a watchdog of public service. It fearlessly investigates public scandals, exposes verified evidence of graft and corruption, and scrutinizes abuses of power, misuse of public funds, and wrongdoing that undermine government integrity and deprive Filipinos of the public services they deserve."}]},{"type":"paragraph","content":[{"type":"text","text":"Guided by credible research, evidence-based investigations, responsible journalism, and editorial independence, Boses ng Bayan stands firmly for truth, fairness, and the public interest. Our commitment is to the Filipino people—not to political parties, powerful personalities, or vested interests. We believe that public office is a public trust, no official is above accountability, and every Filipino deserves honest, transparent, and responsive governance."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Your Voice Matters. Your Right to Know Matters. Your Government Must Answer to You."}]},{"type":"paragraph","content":[{"type":"text","text":"We call on every Filipino to speak up, report suspected corruption, expose wrongdoing through credible evidence, question abuses of authority, and demand accountability from those entrusted with public office. Together, we can challenge corruption, defend public resources, protect democratic institutions, and ensure that government truly serves the people."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Speak Up. Seek the Truth. Expose Corruption. Demand Accountability."}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"BOSES NG BAYAN — Independent in Research. Fearless in Reporting. Uncompromising in Truth."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"For the People. For the Truth. For the Public Interest."}]}]}'::jsonb,
  '<p>Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government.</p><p>More than a public opinion research platform, Boses ng Bayan serves as a watchdog of public service. It fearlessly investigates public scandals, exposes verified evidence of graft and corruption, and scrutinizes abuses of power, misuse of public funds, and wrongdoing that undermine government integrity and deprive Filipinos of the public services they deserve.</p><p>Guided by credible research, evidence-based investigations, responsible journalism, and editorial independence, Boses ng Bayan stands firmly for truth, fairness, and the public interest. Our commitment is to the Filipino people—not to political parties, powerful personalities, or vested interests. We believe that public office is a public trust, no official is above accountability, and every Filipino deserves honest, transparent, and responsive governance.</p><h2>Your Voice Matters. Your Right to Know Matters. Your Government Must Answer to You.</h2><p>We call on every Filipino to speak up, report suspected corruption, expose wrongdoing through credible evidence, question abuses of authority, and demand accountability from those entrusted with public office. Together, we can challenge corruption, defend public resources, protect democratic institutions, and ensure that government truly serves the people.</p><p><strong>Speak Up. Seek the Truth. Expose Corruption. Demand Accountability.</strong></p><hr /><p><strong>BOSES NG BAYAN — Independent in Research. Fearless in Reporting. Uncompromising in Truth.</strong></p><p><em>For the People. For the Truth. For the Public Interest.</em></p>',
  'Boses ng Bayan is an independent public-interest research, news, and investigative journalism platform dedicated to measuring public trust, evaluating governance performance, monitoring public sentiment, and promoting transparency and accountability in government. More than a public opinion research platform, Boses ng Bayan serves as a watchdog of public service. It fearlessly investigates public scandals, exposes verified evidence of graft and corruption, and scrutinizes abuses of power, misuse of public funds, and wrongdoing that undermine government integrity and deprive Filipinos of the public services they deserve. Guided by credible research, evidence-based investigations, responsible journalism, and editorial independence, Boses ng Bayan stands firmly for truth, fairness, and the public interest. Our commitment is to the Filipino people—not to political parties, powerful personalities, or vested interests. We believe that public office is a public trust, no official is above accountability, and every Filipino deserves honest, transparent, and responsive governance. Your Voice Matters. Your Right to Know Matters. Your Government Must Answer to You. We call on every Filipino to speak up, report suspected corruption, expose wrongdoing through credible evidence, question abuses of authority, and demand accountability from those entrusted with public office. Together, we can challenge corruption, defend public resources, protect democratic institutions, and ensure that government truly serves the people. Speak Up. Seek the Truth. Expose Corruption. Demand Accountability. BOSES NG BAYAN — Independent in Research. Fearless in Reporting. Uncompromising in Truth. For the People. For the Truth. For the Public Interest.',
  'published',
  now())
on conflict (slug) do update set
  summary = excluded.summary,
  body = excluded.body,
  body_html = excluded.body_html,
  body_text = excluded.body_text,
  status = 'published',
  published_at = coalesce(public.pages.published_at, excluded.published_at);
